function contextText(ticket, session, markdown) {
  const header =
    `Cockpit-Kontext zu ${ticket}, vom Hook geholt. Deine Sitzung: \`${session}\` — ` +
    'gib sie beim Anlegen der Arbeit als `sitzung` mit. Den Kontext nicht noch einmal abrufen.';
